val baseContext = Dispatchers.IO + CoroutineName("network")
val withHandler = baseContext + CoroutineExceptionHandler { _, e -> log(e) }

scope.launch(withHandler) { /* uses IO dispatcher, name, and handler */ }

try {
    fetchData()
} catch (e: CancellationException) {
    throw e // must propagate — never swallow
} catch (e: IOException) {
    handleError(e)
}

try {
    doWork()
} finally {
    withContext(NonCancellable) {
        releaseRemoteLock() // completes even though the coroutine is cancelled
    }
}

val handler = CoroutineExceptionHandler { _, e -> log("Uncaught: $e") }
val scope = CoroutineScope(SupervisorJob() + handler)

scope.launch { throw RuntimeException("boom") } // handler fires — root coroutine
// scope.launch { launch { throw ... } } // also fires — handler applies down the tree

suspend fun processLargeDataset(items: List<Item>) {
    for ((index, item) in items.withIndex()) {
        processItem(item)
        if (index % 1000 == 0) yield() // cooperative cancellation checkpoint
    }
}

val mutex = Mutex()
var counter = 0

suspend fun increment() = mutex.withLock {
    counter++ // safe even with suspend calls elsewhere in the critical section
}

suspend fun loadAndFormat(): String {
    val raw = withContext(Dispatchers.IO) { file.readText() } // sequential switch
    return withContext(Dispatchers.Default) { formatText(raw) } // switches again, sequentially
}

suspend fun computeSum(items: List<Int>): Int {
    var sum = 0
    for (item in items) {
        currentCoroutineContext().ensureActive() // cheap check, no thread yield
        sum += item
    }
    return sum
}

scope.launch { sendAnalyticsEvent() } // no result needed

val deferred = scope.async { fetchUserProfile() }
val profile = deferred.await() // result + exception surface here

suspend fun retryWithDelay() {
    repeat(3) { attempt ->
        try {
            return fetchData()
        } catch (e: IOException) {
            delay(1000L * (attempt + 1)) // thread stays free during the wait
        }
    }
}

class MyViewModel : ViewModel() {
    private val supervisor = SupervisorJob()
    private val scope = CoroutineScope(Dispatchers.Main.immediate + supervisor)

    fun loadEverything() {
        scope.launch { loadProfile() }   // failure here...
        scope.launch { loadStats() }     // ...won't cancel this
    }

    override fun onCleared() { scope.cancel() } // a hand-made scope must be cancelled
}

// ✅ Good — scoped to ViewModel lifecycle
class MyViewModel : ViewModel() {
    fun loadData() {
        viewModelScope.launch {
            val data = repository.fetchData()
            _state.value = data
        }
    }
}

// ❌ Bad — never cancelled, potential leak
GlobalScope.launch {
    repository.fetchData()
}

// Sequential — takes ~2 seconds
val user = fetchUser()       // 1 sec
val posts = fetchPosts()     // 1 sec

// Parallel — takes ~1 second
coroutineScope {
    val user = async { fetchUser() }
    val posts = async { fetchPosts() }
    showProfile(user.await(), posts.await())
}

fun main() = runBlocking {
    repeat(100_000) {
        launch {
            delay(1_000)     // suspends: the thread is free meanwhile
            counter.incrementAndGet()
        }
    }
} // finishes in about a second, not 100,000 seconds

// Fine: the entry point of a program, or a test
fun main() = runBlocking { println(fetchGreeting()) }

// Wrong in an app: blocks the main thread until the network call returns
fun onClick() {
    val user = runBlocking { api.loadUser() }
}

// Right: start a coroutine and update state when it finishes
fun onClick() {
    viewModelScope.launch { _state.value = api.loadUser() }
}

class ArticleRepository(
    private val api: ArticleApi,
    private val io: CoroutineDispatcher = Dispatchers.IO
) {
    // Main-safe: callers never need to think about threads
    suspend fun load(id: String): Article = withContext(io) {
        api.fetchBlocking(id)
    }
}

viewModelScope.launch { _state.value = repository.load("42") } // called from Main

var searchJob: Job? = null

fun onQueryChanged(query: String) {
    searchJob?.cancel()                         // drop the stale request
    searchJob = viewModelScope.launch {
        delay(300)                              // debounce
        _results.value = repository.search(query)
    }
}

val job = launch { doWork() }
job.join()                                       // wait for it to finish

coroutineScope {
    val profile = async(start = CoroutineStart.LAZY) { api.profile() }
    val orders = async(start = CoroutineStart.LAZY) { api.orders() }

    if (needsData) {
        profile.start()           // begin both together...
        orders.start()
        show(profile.await(), orders.await())   // ...then wait
    }
    // if needsData is false, neither request is ever made
}

fun refresh() {
    viewModelScope.launch {                    // Dispatchers.Main.immediate
        _state.value = UiState.Loading         // applied immediately, before returning
        _state.value = UiState.Content(repository.load())
    }
}

// At most 2 uploads at any moment, without a new thread pool
private val uploadDispatcher = Dispatchers.IO.limitedParallelism(2)

suspend fun upload(files: List<File>) = coroutineScope {
    files.forEach { file -> launch(uploadDispatcher) { api.upload(file) } }
}

// Serialized access to shared state
private val stateDispatcher = Dispatchers.Default.limitedParallelism(1)
suspend fun add(item: Item) = withContext(stateDispatcher) { items.add(item) }
